export default function NavbarSVG() {
  const svgRef = useRef<SVGSVGElement>(null)

  useEffect(() => {
    if (svgRef.current) {
      svgRef.current.innerHTML = SVG_INNER
    }
  }, [])

  return (
    <svg
      ref={svgRef}
      width="100%"
      height="155"
      viewBox="0 8.667 1905 155.333"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
      style={{ display: 'block' }}
    />
  )
}
